// Snow Globe toggle: A pixel cottage in a glass globe. The marble rolls through golden hour into night, and back through dawn.
// One file, no dependencies. From https://zerowing.in/toggles/
//
// Use it:
//   <script type="module" src="snowglobe.js"></script>
//
//   <tg-snowglobe style="display:block; width:360px; height:220px"></tg-snowglobe>
//
//   <script type="module">
//     const t = document.querySelector("tg-snowglobe");
//     t.addEventListener("change", (e) => console.log("on?", e.detail.checked));
//     // t.checked = true;  t.toggle();
//   </script>
//
// API: the `checked` attribute / .checked property, .toggle(), a "change" event ({detail: {checked}}).
// The switch scales to fit its box (designed at 360x220); fill="0.9" sets how much of the box it fills (default 0.82).
// The element paints its own scene background, so give it a rounded container if you want one.

// ---- shared base ----
// Shared base for every toggle in the library.
//
// Contract (every components/<id>.js follows it):
//   - `export default class extends ToggleBase` and `customElements.define('tg-<id>', …)` at the bottom.
//   - Override `template()` → HTML string for the shadow root (include its own <style>).
//     Everything is drawn inside a fixed design stage of W×H px (static W/H, default 360×220);
//     the base scales that stage to fit the host. The host itself is the full scene (paint
//     :host's background yourself if the style swaps day/night etc.).
//   - Override `render(on, instant)` → apply the on/off state. `instant` is true on first paint.
//   - Optional `tick(t, dt)` → called every animation frame while connected (t in ms, from
//     performance.now(), so a virtual clock can drive it). Return nothing.
//   - Any element with [data-hit] is the clickable switch; clicking it calls this.toggle().
//   - Time sources: only performance.now() / rAF / CSS transitions & animations. No setTimeout
//     chains for visible motion (capture seeks a virtual clock).
//
// Public API on every element: .checked (bool, reflects the `checked` attribute), .toggle(),
// 'change' event with detail {checked}. this.scale = current stage scale, this.dpr = devicePixelRatio.

class ToggleBase extends HTMLElement {
  static W = 360;
  static H = 220;
  static observedAttributes = ['checked'];

  constructor() {
    super();
    this.root = this.attachShadow({ mode: 'open' });
    this.scale = 1;
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this._raf = 0;
    this._last = 0;
  }

  template() { return ''; }
  render(_on, _instant) {}
  tick(_t, _dt) {}
  onResize() {}

  connectedCallback() {
    if (!this._built) {
      const { W, H } = this.constructor;
      this.root.innerHTML = `
        <style>
          :host { display: block; position: relative; overflow: hidden; contain: content; -webkit-tap-highlight-color: transparent; }
          .tg-stage { position: absolute; left: 50%; top: 50%; width: ${W}px; height: ${H}px;
            transform: translate(-50%, -50%) scale(var(--s, 1)); transform-origin: 50% 50%; }
          [data-hit] { cursor: pointer; }
        </style>
        <div class="tg-stage">${this.template()}</div>`;
      this.stage = this.root.querySelector('.tg-stage');
      this.root.addEventListener('click', (e) => {
        if (e.composedPath().some((n) => n instanceof Element && n.hasAttribute('data-hit'))) this.toggle();
      });
      this._built = true;
      this.setup?.();
      this.render(this.checked, true);
    }
    this._ro = new ResizeObserver(() => this._fit());
    this._ro.observe(this);
    this._fit();
    const loop = (t) => {
      const dt = this._last ? Math.min(t - this._last, 64) : 16;
      this._last = t;
      this.tick(t, dt);
      this._raf = requestAnimationFrame(loop);
    };
    this._raf = requestAnimationFrame(loop);
  }

  disconnectedCallback() {
    cancelAnimationFrame(this._raf);
    this._ro?.disconnect();
    this._last = 0;
  }

  _fit() {
    const { W, H } = this.constructor;
    const r = this.getBoundingClientRect();
    if (!r.width || !r.height) return;
    // Toggle fills ~78% of the shorter fit so every tile has breathing room.
    this.scale = Math.min(r.width / W, r.height / H) * (parseFloat(this.getAttribute('fill')) || 0.82);
    this.style.setProperty('--s', this.scale);
    this.onResize();
  }

  get checked() { return this.hasAttribute('checked'); }
  set checked(v) { this.toggleAttribute('checked', !!v); }

  attributeChangedCallback(name, oldV, newV) {
    if (name === 'checked' && this._built && (oldV === null) !== (newV === null)) {
      this.render(this.checked, false);
      this.dispatchEvent(new CustomEvent('change', { detail: { checked: this.checked }, bubbles: true }));
    }
  }

  toggle() { this.checked = !this.checked; }

  $(sel) { return this.root.querySelector(sel); }
  $$(sel) { return [...this.root.querySelectorAll(sel)]; }

  // Size a <canvas> to cover `w×h` design px at full device resolution.
  sizeCanvas(cv, w, h) {
    const k = this.scale * this.dpr;
    cv.width = Math.max(1, Math.round(w * k));
    cv.height = Math.max(1, Math.round(h * k));
    cv.style.width = w + 'px';
    cv.style.height = h + 'px';
    const ctx = cv.getContext('2d');
    ctx.setTransform(k, 0, 0, k, 0, 0);
    return ctx;
  }
}

// Easing helpers shared by components.
const ease = {
  outCubic: (x) => 1 - Math.pow(1 - x, 3),
  inOutCubic: (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2),
  outBack: (x, s = 1.70158) => 1 + (s + 1) * Math.pow(x - 1, 3) + s * Math.pow(x - 1, 2),
  // Critically-damped-ish spring step: returns new [pos, vel].
  spring: (pos, vel, target, dt, k = 170, d = 18) => {
    const s = dt / 1000;
    const a = -k * (pos - target) - d * vel;
    vel += a * s;
    pos += vel * s;
    return [pos, vel];
  },
};

const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const lerp = (a, b, t) => a + (b - a) * t;

// ---- Snow Globe ----
// 01 · Snow Globe — pixel-art cottage diorama inside a clay pill; a clear glass marble rolls
// across, magnifying the scene. Three acts: it rolls off, slows and pauses near the centre for
// GOLDEN HOUR (sun on the ridge, amber/rose sky, long shadows, the figure silhouetted, birds
// crossing), then rolls on into night. The reverse pauses at DAWN instead. checked = night.

const SW = 120, SH = 52;          // pixel scene resolution
const WIN_W = 300, WIN_H = 130;   // window in design px (2.5 px per scene px)
const PX = WIN_W / SW;
const R = 56;                     // marble radius
const M = 1.32;                   // marble magnification
const DUR = 2050;                 // full timeline (ms)
const P1 = 0.2, P2 = 0.7;          // leave | middle act | arrive
const N1 = 0.42, N2 = 0.52;        // time of day held during the middle act (golden hour / dawn)

const H = (h) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
const mix = (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
const rgb = (c) => `rgb(${c[0] | 0},${c[1] | 0},${c[2] | 0})`;
const tri = (d, u, n, x) => (x < 0.5 ? mix(d, u, x * 2) : mix(u, n, (x - 0.5) * 2));
const grad = (stops, f) => {
  const s = stops.length - 1, i = Math.min(s - 1, Math.floor(f * s));
  return mix(stops[i], stops[i + 1], f * s - i);
};

// [day, dusk, night]
const PAL = Object.fromEntries(Object.entries({
  grass: ['#8cc66a', '#a39050', '#18264c'], grass2: ['#74b050', '#857a40', '#0f1a3a'],
  tuft: ['#5c9a3e', '#6a5a30', '#24346a'], mtn: ['#a8b3dc', '#8a6898', '#1c265a'],
  mtnHi: ['#c4cceb', '#b08aa8', '#5464aa'], path: ['#e0cc98', '#cf9e6c', '#2b3264'],
  wall: ['#f5f2ea', '#efc6a2', '#46528a'], wallLine: ['#dcd8ce', '#d6a888', '#313a66'],
  roof: ['#3f66bc', '#4a4890', '#2c3878'], roofLine: ['#30519c', '#3a3878', '#1c2658'],
  chim: ['#b8664a', '#a85240', '#3a2a44'], frame: ['#2f57ab', '#3a3f86', '#222b56'],
  glass: ['#d7edf9', '#ffd0a0', '#2a3466'], door: ['#2b3f7c', '#2a2f66', '#151b3c'],
  fence: ['#cc9c60', '#b8784a', '#3d3f66'], fenceHi: ['#e2b67a', '#d09060', '#4a4c74'],
  bench: ['#8c5c34', '#7a4a2a', '#282a46'], hair: ['#2a2030', '#2a2030', '#14142a'],
  skin: ['#f2c9a2', '#e8a882', '#5c5e88'], shirt: ['#ffffff', '#ffd9bc', '#7c84ae'],
  pants: ['#3256a8', '#3a3a80', '#1c2352'], trunk: ['#7a5232', '#6a4028', '#141a36'],
  trunkLo: ['#5c3c24', '#4e2e1e', '#0c1028'], leaf: ['#4f8c3a', '#5c6a30', '#0a1030'],
  leafHi: ['#78b24e', '#8c8a40', '#4a66c0'], leafLo: ['#3a6a2c', '#3a4628', '#080d2e'],
  cloud: ['#ffffff', '#ffb9a4', '#3a4270'], stone: ['#b8b4aa', '#a89080', '#3a3e60'],
  sun: ['#fff4b8', '#ff9548', '#ff5a3a'],
}).map(([k, v]) => [k, v.map(H)]));

const SKY_DAY = ['#7fbfe8', '#a8d6f2', '#c8e8f8'].map(H);
const SKY_GOLD = ['#4a3a7a', '#a8558a', '#e8706a', '#ff9f5a', '#ffd27e'].map(H);
const SKY_DAWN = ['#3e4886', '#9a78b4', '#ee9fb2', '#ffbfa8', '#ffe2c4'].map(H);
const SILH = H('#2b1b2e');
const BIRDS = [{ dx: 0, y: 13, ph: 0 }, { dx: 8, y: 17, ph: 1.7 }, { dx: 15, y: 11, ph: 3.1 }];
const SKY_NIGHT = ['#0a0f2e', '#1f2b68', '#3b4b94'].map(H);

// deterministic sprinkles
function rng(seed) {
  return () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}
const r = rng(7);
const STARS = Array.from({ length: 30 }, () => ({ x: (r() * SW) | 0, y: 1 + ((r() * 25) | 0), ph: r() * 6.28, sp: 0.6 + r() * 1.2, warm: r() < 0.3 }))
  .filter((s) => Math.hypot(s.x - 18, s.y - 8) > 7 && !(s.x > 90 && s.x < 111 && s.y > 11));
const SPARKLES = [{ x: 44, y: 6 }, { x: 72, y: 11 }, { x: 116, y: 4 }];
const TUFTS = Array.from({ length: 34 }, () => ({ x: (r() * SW) | 0, y: 41 + ((r() * 11) | 0) }));
const DANDS = Array.from({ length: 12 }, () => ({ x: 62 + ((r() * 56) | 0), y: 45 + ((r() * 6) | 0), puff: r() < 0.3 }));
const FLIES = Array.from({ length: 7 }, (_, i) => ({ x: 60 + r() * 56, y: 30 + r() * 16, i }));
const hM = (x) => Math.round(29 + 2.5 * Math.sin(x * 0.08 + 0.5) + 1.5 * Math.sin(x * 0.21));
const hH = (x) => Math.round(36 + 1.4 * Math.sin(x * 0.11 + 2) + 0.8 * Math.sin(x * 0.3));

export default class SnowGlobe extends ToggleBase {
  template() {
    return `
<style>
  .sg { position: absolute; left: 15px; top: 30px; width: 330px; height: 160px; border-radius: 80px; }
  .glow { position: absolute; left: 34px; right: 34px; bottom: -30px; height: 70px; border-radius: 50%;
    background: radial-gradient(closest-side, rgba(255,168,64,.62), rgba(255,140,40,0)); filter: blur(10px);
    opacity: var(--glow, 0); transition: opacity .45s ease; }
  .bezel { position: absolute; inset: 0; border-radius: 80px; background: var(--bz, #EAE7DF);
    box-shadow: 0 26px 44px -20px rgba(30,24,16,var(--sh,.45)), 0 8px 16px -8px rgba(30,24,16,var(--sh,.3)),
      inset 0 2px 1px rgba(255,255,255,var(--hl,.9)), inset 0 -4px 8px rgba(0,0,0,.14); }
  .rim { position: absolute; inset: 0; border-radius: 80px; pointer-events: none;
    box-shadow: inset 0 -3px 3px -1px rgba(255,186,96,var(--rim,0)); transition: box-shadow .45s ease; }
  .win { position: absolute; left: 15px; top: 15px; width: ${WIN_W}px; height: ${WIN_H}px; border-radius: 65px; overflow: hidden; background: #000; }
  canvas { position: absolute; left: 0; top: 0; }
  .lip { position: absolute; inset: 0; border-radius: 65px; pointer-events: none;
    box-shadow: inset 0 6px 9px rgba(0,0,0,.38), inset 0 -2px 3px rgba(255,255,255,.16), inset 0 0 0 1.5px rgba(0,0,0,.28); }
</style>
<div class="sg" data-hit>
  <div class="glow"></div><div class="bezel"></div><div class="rim"></div>
  <div class="win"><canvas></canvas><div class="lip"></div></div>
</div>`;
  }

  setup() {
    this.cv = this.$('canvas');
    this.sc = document.createElement('canvas');
    this.sc.width = SW; this.sc.height = SH;
    this.g = this.sc.getContext('2d');
    this.sg = this.$('.sg');
    this.p = this.checked ? 1 : 0;
    this._dir = this.checked ? 1 : -1;
    this.dw = this.checked ? 0 : 1;   // 0 = golden-hour palette (going to night), 1 = dawn palette
    this._styled = '';
  }

  onResize() {
    this.ctx = this.sizeCanvas(this.cv, WIN_W, WIN_H);
    this.ctx.imageSmoothingEnabled = false;
  }

  render(on, instant) {
    this._dir = on ? 1 : -1;
    if (instant) { this.p = on ? 1 : 0; this.dw = on ? 0 : 1; }
  }

  // marble position along the window: roll off, slow to a near-stop around the centre, roll on
  posOf(p) {
    if (p < P1) return 0.46 * ease.inOutCubic(p / P1);
    if (p < P2) return 0.46 + 0.08 * ((p - P1) / (P2 - P1));
    return 0.54 + 0.46 * ease.inOutCubic((p - P2) / (1 - P2));
  }

  // time of day: 0 day … ~0.47 golden hour/dawn … 1 night
  dayOf(p) {
    if (p < P1) return N1 * ease.inOutCubic(p / P1);
    if (p < P2) return N1 + (N2 - N1) * ((p - P1) / (P2 - P1));
    return N2 + (1 - N2) * ease.inOutCubic((p - P2) / (1 - P2));
  }

  tick(t, dt) {
    const target = this.checked ? 1 : 0;
    if (this.p !== target) this.p = target > this.p ? Math.min(target, this.p + dt / DUR) : Math.max(target, this.p - dt / DUR);
    const p = this.p;
    // palette follows the travel direction; blend so a mid-way reversal doesn't pop
    this.dw += ((this._dir > 0 ? 0 : 1) - this.dw) * (1 - Math.exp(-dt / 220));
    this.pos = this.posOf(p);
    const n = this.dayOf(p);
    const mid = clamp((p - 0.1) / 0.14) * clamp((0.8 - p) / 0.14);      // middle-act amount
    const u = this._dir > 0 ? p : 1 - p;                                 // progress in travel direction
    this.birdT = clamp((u - P1 + 0.06) / (P2 - P1 + 0.08));
    if (!this.ctx) return;
    this.drawScene(n, t, mid, this.dw);
    const c = this.ctx;
    c.clearRect(0, 0, WIN_W, WIN_H);
    c.drawImage(this.sc, 0, 0, SW, SH, 0, 0, WIN_W, WIN_H);
    this.drawMarble(c, n, mid);
    this.applyStyles(n, mid, this.dw);
  }

  applyStyles(n, mid, dw) {
    const key = n.toFixed(3) + mid.toFixed(3) + dw.toFixed(2);
    if (key === this._styled) return;
    this._styled = key;
    const lit = n > 0.8;
    const warm = mix(H('#E7C29C'), H('#E6C2C6'), dw), warmHi = mix(H('#F6DDBE'), H('#F5DCDD'), dw);
    let bg = mix(H('#F5F3EC'), H('#1B1D28'), n), bgHi = mix(H('#FCFBF7'), H('#272A3B'), n);
    bg = mix(bg, warm, mid * 0.8); bgHi = mix(bgHi, warmHi, mid * 0.8);
    this.style.background = `radial-gradient(120% 95% at 50% 42%, ${rgb(bgHi)}, ${rgb(bg)})`;
    const s = this.sg.style;
    s.setProperty('--bz', rgb(mix(mix(H('#EAE7DF'), H('#2A2E41'), n), mix(H('#E2C3A2'), H('#DDC0C4'), dw), mid * 0.75)));
    s.setProperty('--hl', lerp(0.9, 0.14, n).toFixed(3));
    s.setProperty('--sh', lerp(0.45, 0.7, n).toFixed(3));
    s.setProperty('--glow', lit ? '1' : (mid * 0.55).toFixed(3));
    s.setProperty('--rim', lit ? '.75' : '0');
  }

  drawScene(n, t, mid = 0, dw = 0) {
    const g = this.g;
    const P = (x, y, w, h, c) => { g.fillStyle = c; g.fillRect(x, y, w, h); };
    const k = {};
    for (const key in PAL) k[key] = rgb(tri(...PAL[key], n));
    // golden hour: the figure and bench go to silhouette against the low sun
    for (const key of ['hair', 'skin', 'shirt', 'pants', 'bench']) k[key] = rgb(mix(tri(...PAL[key], n), SILH, mid * 0.85));
    const A = (a) => { g.globalAlpha = clamp(a); };
    const disc = (cx, cy, rr, c) => {
      g.fillStyle = c;
      for (let dy = -rr; dy <= rr; dy++) {
        const hw = Math.floor(Math.sqrt(Math.max(0, (rr + 0.4) ** 2 - dy * dy)));
        g.fillRect(cx - hw, cy + dy, hw * 2 + 1, 1);
      }
    };
    A(1);

    // sky: banded + dithered, day → dusk → night
    const rows = [];
    for (let y = 0; y < 40; y++) {
      const f = Math.min(1, Math.floor(y / 4) / 9);
      rows[y] = rgb(tri(grad(SKY_DAY, f), mix(grad(SKY_GOLD, f), grad(SKY_DAWN, f), dw), grad(SKY_NIGHT, f), n));
    }
    for (let y = 0; y < 40; y++) {
      P(0, y, SW, 1, rows[y]);
      if (y % 4 === 3 && y + 1 < 40) { g.fillStyle = rows[y + 1]; for (let x = (y >> 2) & 1; x < SW; x += 2) g.fillRect(x, y, 1, 1); }
    }

    // stars + sparkles
    const sa = clamp((n - 0.6) / 0.3);
    if (sa > 0) {
      for (const s of STARS) { A(sa * (0.5 + 0.5 * Math.sin(t * 0.0025 * s.sp + s.ph))); P(s.x, s.y, 1, 1, s.warm ? '#fff1c0' : '#eef2ff'); }
      for (const [i, s] of SPARKLES.entries()) {
        const tw = 0.5 + 0.5 * Math.sin(t * 0.002 + i * 2.1);
        A(sa); P(s.x, s.y, 1, 1, '#ffffff');
        A(sa * tw * 0.8); P(s.x - 1, s.y, 1, 1, '#dfe6ff'); P(s.x + 1, s.y, 1, 1, '#dfe6ff'); P(s.x, s.y - 1, 1, 1, '#dfe6ff'); P(s.x, s.y + 1, 1, 1, '#dfe6ff');
        A(sa * tw * 0.35); P(s.x - 2, s.y, 1, 1, '#dfe6ff'); P(s.x + 2, s.y, 1, 1, '#dfe6ff'); P(s.x, s.y - 2, 1, 1, '#dfe6ff'); P(s.x, s.y + 2, 1, 1, '#dfe6ff');
      }
    }

    // moon rises
    const ma = clamp((n - 0.55) / 0.35);
    if (ma > 0) {
      const my = Math.round(8 + (1 - ease.outCubic(ma)) * 9);
      A(ma * 0.1); disc(18, my, 9, '#dfe4ff');
      A(ma * 0.16); disc(18, my, 6, '#eef0ff');
      A(ma); disc(18, my, 4, '#f6f1dc');
      A(ma * 0.8); P(16, my - 1, 2, 1, '#ddd5b8'); P(19, my + 1, 1, 2, '#ddd5b8'); P(17, my + 2, 1, 1, '#ddd5b8');
    }

    // sun rides down onto the ridge, sits on it through the middle act, then sinks behind it
    if (n < 0.64) {
      const sx = Math.round(94 - ease.inOutCubic(clamp(n / N1)) * 26 - clamp((n - N1) / 0.2) * 3);
      const ridge = hM(sx);
      const sy = n < N1 ? Math.round(7 + (ridge - 4 - 7) * ease.inOutCubic(n / N1))
        : n < N2 ? Math.round(ridge - 5 + ((n - N1) / (N2 - N1)) * 3)
        : Math.round(ridge - 2 + ((n - N2) / (0.62 - N2)) * 8);
      const sc = rgb(mix(tri(...PAL.sun, n), H('#ffb07a'), dw * 0.5));
      if (mid > 0) {                                   // big low-sun glow + light along the horizon
        A(0.12 * mid); disc(sx, sy, 15, '#ffd890');
        A(0.2 * mid); disc(sx, sy, 10, '#ffc874');
        for (let y = ridge - 4; y < ridge + 2; y++) { A(mid * (0.22 - Math.abs(y - ridge + 1) * 0.04)); P(0, y, SW, 1, dw > 0.5 ? '#ffd2c0' : '#ffd08a'); }
      }
      A(0.18 + 0.2 * clamp(n / N1)); disc(sx, sy, 8, sc);
      A(0.3 + 0.2 * clamp(n / N1)); disc(sx, sy, 6, sc);
      A(1); disc(sx, sy, 4 + Math.round(mid), sc);
      if (mid > 0) { A(mid); disc(sx, sy, 3, dw > 0.5 ? "#fff0d8" : "#fff2b8"); A(mid * 0.9); disc(sx, sy, 1, "#ffffff"); }
      A(0.7); P(sx - 2, sy - 2, 2, 1, '#fffbe6');
      this.sunX = sx;
    }

    // birds crossing the golden sky
    if (mid > 0.02) {
      for (const b of BIRDS) {
        const x = Math.round(128 - this.birdT * 150 + b.dx);
        const y = Math.round(b.y + Math.sin(t * 0.003 + b.ph) * 1.2);
        const up = Math.floor(t / 150 + b.ph) % 2 === 0;
